fn one_off(a: Str, b: Str) -> Bool {
  if a.len() != b.len() {
    return false
  }
  let diffs = a.chars().zip(b.chars()).count(fn(p) => p.first != p.second)
  return diffs == 1
}

fn bfs(goal: Str, pool: List[Str], frontier: List[Str], visited: List[Str], level: Int) -> Int {
  if frontier.is_empty() {
    return 0
  }
  if frontier.contains(goal) {
    return level
  }
  let nxt = pool.filter(fn(w) => (not visited.contains(w)) and frontier.any(fn(f) => one_off(f, w)))
  return bfs(goal: goal, pool: pool, frontier: nxt, visited: visited.concat(nxt), level: level + 1)
}

pub fn ladder(start: Str, goal: Str, words: List[Str]) -> Int {
  if start == goal {
    return 1
  }
  let pool = words.unique()
  let first: List[Str] = [start]
  return bfs(goal: goal, pool: pool, frontier: first, visited: first, level: 1)
}
